((a,i)=>{a.behaviors.clipboardCopy={attach:function(r){i("clipboardCopy",'a[href^="mailto:"], a[href^="tel:"]',r).forEach(e=>{e.addEventListener("click",c=>{c.preventDefault();const o=e.getAttribute("href");let t="";o.startsWith("mailto:")?(t=o.replace("mailto:",""),t=t.split("?")[0]):o.startsWith("tel:")&&(t=o.replace("tel:","")),t&&navigator.clipboard.writeText(t).then(()=>{e.classList.add("is-copied-to-clipboard"),setTimeout(()=>{e.classList.remove("is-copied-to-clipboard")},2e3)}).catch(l=>{console.error("Failed to copy to clipboard: ",l)})})})}}})(Drupal,once);
